\set ON_ERROR_STOP on
BEGIN;
DO $$ DECLARE
 p UUID:='a1000000-0000-4000-8000-000000000001'; p2 UUID:='a1000000-0000-4000-8000-000000000002';
 b UUID:='b1000000-0000-4000-8000-000000000001'; b2 UUID:='b1000000-0000-4000-8000-000000000002';
 u UUID:='c1000000-0000-4000-8000-000000000001'; pr1 UUID:='d1000000-0000-4000-8000-000000000001'; pr2 UUID:='d1000000-0000-4000-8000-000000000002';
 op UUID:='e1000000-0000-4000-8000-000000000001'; op2 UUID:='e1000000-0000-4000-8000-000000000002';
 h1 TEXT;h2 TEXT;r RECORD;caught BOOLEAN;before_purchase BIGINT;before_item BIGINT;before_batch BIGINT;before_ledger BIGINT;before_audit BIGINT;before_evidence BIGINT;failure_state TEXT;failure_message TEXT;
 items1 JSONB:=jsonb_build_array(jsonb_build_object('product_id',pr2,'batch_number','B','expiry_date','2027-02-01','quantity',2),jsonb_build_object('product_id',pr1,'batch_number','A','expiry_date','2027-01-01','quantity',1,'cost_price',0,'selling_price',0));
 items2 JSONB:=jsonb_build_array(jsonb_build_object('product_id',pr1,'batch_number','A','expiry_date','2027-01-01','quantity',1),jsonb_build_object('product_id',pr2,'batch_number','B','expiry_date','2027-02-01','quantity',2,'cost_price',0,'selling_price',0));
BEGIN
 IF EXISTS(SELECT 1 FROM public.pharmacies WHERE id IN(p,p2)) OR EXISTS(SELECT 1 FROM auth.users WHERE id=u OR email='pf-mvp10@example.invalid') OR EXISTS(SELECT 1 FROM public.branches WHERE id IN(b,b2)) OR EXISTS(SELECT 1 FROM public.products WHERE id IN(pr1,pr2)) THEN RAISE EXCEPTION 'PREEXISTING_TRANSACTIONAL_FIXTURE';END IF;
 INSERT INTO auth.users(id,aud,role,email,created_at,updated_at) VALUES(u,'authenticated','authenticated','pf-mvp10@example.invalid',now(),now());
 INSERT INTO public.pharmacies(id,name,owner_id) VALUES(p,'PF MVP10 A',u),(p2,'PF MVP10 B',u);
 INSERT INTO public.branches(id,pharmacy_id,name,is_main) VALUES(b,p,'A',true),(b2,p2,'B',true);
 INSERT INTO public.pharmacy_members(user_id,pharmacy_id,role,default_branch_id,status) VALUES(u,p,'OWNER',b,'ACTIVE');
 INSERT INTO public.subscriptions(pharmacy_id,plan_code,status,current_period_start,current_period_end) VALUES(p,'TRIAL','ACTIVE',now()-interval '1 day',now()+interval '1 day');
 INSERT INTO public.products(id,pharmacy_id,name,selling_price) VALUES(pr1,p,'One',1),(pr2,p,'Two',1);
 PERFORM set_config('request.jwt.claim.sub',u::TEXT,true);PERFORM set_config('request.jwt.claim.role','authenticated',true);
 h1:=public.entitlement_intake_fingerprint_v2(b,items1,NULL,' INV ');h2:=public.entitlement_intake_fingerprint_v2(b,items2,NULL,'INV');
 IF h1<>h2 THEN RAISE EXCEPTION 'CANONICAL_REORDER_MISMATCH'; END IF;
 IF h1=public.entitlement_intake_fingerprint_v2(b,items2,NULL,'CHANGED') THEN RAISE EXCEPTION 'CHANGED_PAYLOAD_NOT_DISTINCT'; END IF;
 caught:=false;BEGIN PERFORM public.assert_entitlement_operation_v5(p2,b2,NULL,u,'INVENTORY_INTAKE',op,h1,FALSE,FALSE);EXCEPTION WHEN insufficient_privilege THEN caught:=true;END;IF NOT caught THEN RAISE EXCEPTION 'TENANT_ISOLATION_FAILED';END IF;
 caught:=false;BEGIN PERFORM * FROM public.rpc_receive_inventory_stock(p,b2,items1,NULL,'WRONG-BRANCH',NULL,'e1000000-0000-4000-8000-000000000099');EXCEPTION WHEN foreign_key_violation THEN caught:=true;END;IF NOT caught THEN RAISE EXCEPTION 'BRANCH_ISOLATION_FAILED';END IF;
 SELECT * INTO r FROM public.rpc_receive_inventory_stock(p,b,items1,NULL,' INV ',NULL,op);IF r.status<>'COMPLETED' OR r.total_items<>2 THEN RAISE EXCEPTION 'INTAKE_CONTRACT_FAILED';END IF;
 caught:=false;BEGIN PERFORM * FROM public.rpc_receive_inventory_stock(p,b,jsonb_set(items1,'{0,quantity}','3'),NULL,' INV ',NULL,op);EXCEPTION WHEN unique_violation THEN caught:=true;END;IF NOT caught THEN RAISE EXCEPTION 'CHANGED_INTAKE_NOT_CONFLICT';END IF;
 UPDATE public.subscriptions SET status='EXPIRED',current_period_start=now()-interval '9 days',current_period_end=now()-interval '8 days' WHERE pharmacy_id=p;
 SELECT * INTO r FROM public.rpc_receive_inventory_stock(p,b,items2,NULL,'INV',NULL,op);IF r.purchase_id IS NULL THEN RAISE EXCEPTION 'EXPIRED_COMMITTED_REPLAY_FAILED';END IF;
 INSERT INTO public.entitlement_administrative_decisions_v1(pharmacy_id,decision_kind,effective_at,reason,decided_by) VALUES(p,'SUSPEND',now()-interval '2 seconds','test',u);
 IF (public.resolve_effective_entitlement_v3(p)->>'mutations_allowed')::BOOLEAN THEN RAISE EXCEPTION 'SUSPENSION_FAILED';END IF;
 INSERT INTO public.entitlement_administrative_decisions_v1(pharmacy_id,decision_kind,effective_at,reason,decided_by) VALUES(p,'REINSTATE',now()-interval '1 second','test',u);
 IF (public.resolve_effective_entitlement_v3(p)->>'state')<>'EXPIRED' THEN RAISE EXCEPTION 'REINSTATEMENT_MANUFACTURED_COMMERCIAL_STATE';END IF;
 INSERT INTO public.entitlement_administrative_decisions_v1(pharmacy_id,decision_kind,effective_at,reason,decided_by) VALUES(p,'SUSPEND',now()+interval '1 day','future',u);
 IF (public.resolve_effective_entitlement_v3(p)->>'state')<>'EXPIRED' THEN RAISE EXCEPTION 'FUTURE_DECISION_APPLIED_EARLY';END IF;
 UPDATE public.subscriptions SET status='PAST_DUE',current_period_start=now()-interval '30 days',current_period_end=now()-interval '6 days' WHERE pharmacy_id=p;
 IF (public.resolve_effective_entitlement_v3(p)->>'state')<>'GRACE' THEN RAISE EXCEPTION 'GRACE_BOUNDARY_FAILED';END IF;
 UPDATE public.subscriptions SET status='ACTIVE',current_period_start=now()-interval '1 day',current_period_end=now()+interval '1 day' WHERE pharmacy_id=p;
 INSERT INTO public.entitlement_administrative_decisions_v1(pharmacy_id,decision_kind,effective_at,reason,decided_by) VALUES(p,'SUSPEND',now()-interval '0.5 seconds','tie-suspend',u),(p,'REINSTATE',now()-interval '0.5 seconds','tie-reinstate',u);
 IF NOT (public.resolve_effective_entitlement_v3(p)->>'mutations_allowed')::BOOLEAN THEN RAISE EXCEPTION 'DECISION_SEQUENCE_TIE_FAILED';END IF;
 before_purchase:=(SELECT count(*) FROM public.purchases WHERE pharmacy_id=p);before_item:=(SELECT count(*) FROM public.purchase_items WHERE pharmacy_id=p);before_batch:=(SELECT count(*) FROM public.inventory_batches WHERE pharmacy_id=p);before_ledger:=(SELECT count(*) FROM public.stock_ledger WHERE pharmacy_id=p);before_audit:=(SELECT count(*) FROM public.audit_logs WHERE pharmacy_id=p);before_evidence:=(SELECT count(*) FROM public.entitlement_committed_operations_v1 WHERE pharmacy_id=p);caught:=false;
 PERFORM public.assert_entitlement_operation_v5(p,b,NULL,u,'INVENTORY_INTAKE',op2,public.entitlement_intake_fingerprint_v2(b,jsonb_build_array(jsonb_build_object('product_id',pr1,'batch_number','C','expiry_date','2028-01-01','quantity',1)),NULL,'ROLLBACK'),FALSE,FALSE);
 CREATE OR REPLACE FUNCTION pg_temp.reject_evidence() RETURNS trigger LANGUAGE plpgsql AS 'BEGIN RAISE EXCEPTION USING ERRCODE=''P0001'',MESSAGE=''PF_EVIDENCE_BOUNDARY_FORCED''; END';
 CREATE TRIGGER pf_mvp10_reject_evidence BEFORE INSERT ON public.entitlement_committed_operations_v1 FOR EACH ROW EXECUTE FUNCTION pg_temp.reject_evidence();
 BEGIN PERFORM * FROM public.rpc_receive_inventory_stock(p,b,jsonb_build_array(jsonb_build_object('product_id',pr1,'batch_number','C','expiry_date','2028-01-01','quantity',1)),NULL,'ROLLBACK',NULL,op2);EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS failure_state=RETURNED_SQLSTATE,failure_message=MESSAGE_TEXT;caught:=failure_state='P0001' AND failure_message='PF_EVIDENCE_BOUNDARY_FORCED';END;
 IF NOT caught OR (SELECT count(*) FROM public.purchases WHERE pharmacy_id=p)<>before_purchase OR (SELECT count(*) FROM public.purchase_items WHERE pharmacy_id=p)<>before_item OR (SELECT count(*) FROM public.inventory_batches WHERE pharmacy_id=p)<>before_batch OR (SELECT count(*) FROM public.stock_ledger WHERE pharmacy_id=p)<>before_ledger OR (SELECT count(*) FROM public.audit_logs WHERE pharmacy_id=p)<>before_audit OR (SELECT count(*) FROM public.entitlement_committed_operations_v1 WHERE pharmacy_id=p)<>before_evidence THEN RAISE EXCEPTION 'EVIDENCE_FAILURE_NOT_ATOMIC';END IF;
 DROP TRIGGER pf_mvp10_reject_evidence ON public.entitlement_committed_operations_v1;
END $$;
ROLLBACK;
SELECT 'PF_PASS|transactional-scenarios-rolled-back';
